/* Lantern Path by Theo · r6 (v6.1, v1.5 tokens)
   One idea: a quiet autumn path. Day = misty amber morning on paper; night = lantern light on walnut.
   The art frames the edges, the middle is a calm reading column. One signature: an inked maple leaf
   on the corner of every card (and on the scene-break rule), a few leaves drifting behind the cards.
   Fonts: Fraunces 600 (SIL Open Font License 1.1). Art: Codex image model (owner's), prompted by Theo; night twins, focus frames and thumbnail derived by Theo. */
:root {
  --mari-tokens-version: 1;
  --radius: 10px;
  --mari-font-heading: "Fraunces", Georgia, serif;
  --mari-selected-tint: var(--primary);
  --mari-msg-head-rule: none;
  --mari-home-widget-radius: 12px;
  --mari-home-widget-border-width: 0px;
  --mari-home-widget-title-font: "Fraunces", Georgia, serif;
  --mari-home-widget-title-size: 24px;
  --mari-home-widget-text-size: 14px;
  --mari-home-widget-eyebrow-size: 11px;
  --mari-home-widget-glow: none;
  --mari-home-art: none;
  --mari-chat-font-size: 16px;
  --mari-text-outline: 0;
  --mari-min-ui-text: 12px;
  --mari-toast-font-size: 14px;
  --mari-composer-placeholder: "Write by lantern light…";
  --mari-cursor: url("theme:cursor-leaf.png") 4 4, auto;
  --mari-chat-radius: 12px;
  --mari-chat-wash: none;
  /* Room for the auto-hiding top bar so the greeting is never cut when it slides in. */
  --mari-home-hero-padding: calc(var(--mari-top-bar-height, 44px) + 6px) .25rem 1rem;
  --mari-app-backdrop-attachment: fixed;
  /* Leaves drift BEHIND the cards and only in the side gutters (v1.4 slot: no hand masks). */
  --mari-ambient: url("theme:ambient-leaves.webp") 0 0 / 448px 448px repeat;
  --mari-ambient-opacity: 0.7;
  --mari-ambient-animation: theo-leaves 80s linear infinite;
  --mari-ambient-placement: behind-cards;
  /* The clear band follows the chat area's centre, which the app publishes as --mari-center-x. */
  --theo-cx: var(--mari-center-x, 50%);
  --theo-clear: 25rem;
  --mari-ambient-mask: linear-gradient(90deg, #000 0, #000 calc(var(--theo-cx) - var(--theo-clear) - 3rem),
    #0000 calc(var(--theo-cx) - var(--theo-clear)), #0000 calc(var(--theo-cx) + var(--theo-clear)),
    #000 calc(var(--theo-cx) + var(--theo-clear) + 3rem), #000 100%);
  /* Reading column (v1.5): cards and the message box share one ~70-characters-a-line column. */
  --mari-chat-column: 39rem;
  --mari-message-measure: 70ch;
  --mari-chat-line-height: 1.62;
  --mari-dialogue-weight: 500;
  --mari-paragraph-gap: .8em;
  --mari-pinned-speaker: on;
  --mari-pinned-speaker-bleed: 1rem;
  --mari-pinned-speaker-bg: var(--theo-panel-solid);
  --mari-phone-avatar: hidden;
  --mari-focus-frame-outset: 0px;
  --mari-chat-row-art-opacity: 0.1;
  --mari-vn-fade: 2rem;
  --theo-shadow: 0 1px 2px #3b2a1e14, 0 8px 24px #3b2a1e1f;
  --theo-frame: url("theme:frame-card.webp");
}
@keyframes theo-leaves { to { background-position: 448px 896px; } }
/* Leaves rest on phones (the column is the whole width) and on long-text pages. */
@media (max-width: 640px) { :root { --mari-ambient: none; } }
:root:has([data-component="CenterContent"][data-center-page]) { --mari-ambient: none; }
/* Game: the party panel sits on the right, so leaves fall on the stage side only. */
:root[data-chat-open-mode="game"] {
  --mari-ambient-mask: linear-gradient(90deg, #000 0, #000 56%, #0000 64%);
}

/* ---------- DAY: misty amber morning ---------- */
:root[data-theme="light"] {
  --background: #f6ecdc; --foreground: #3b2a1e;
  --card: #fbf4e8f0; --card-foreground: #3b2a1e;
  --popover: #fbf4e8; --popover-foreground: #3b2a1e;
  --primary: #a63f24; --primary-foreground: #fffaf2;
  --secondary: #efe2cc; --secondary-foreground: #3b2a1e;
  --muted: #efe3cf; --muted-foreground: #6a5444;
  --accent: #f2dcc0; --accent-foreground: #3b2a1e;
  --destructive: #a3261b; --destructive-foreground: #fffaf2;
  --border: #b5462a38; --input: #b5462a52; --ring: #a63f24;
  --sidebar: #fbf4e8eb; --sidebar-foreground: #3b2a1e; --sidebar-border: #b5462a2e;
  --sidebar-accent: #f2e2c8; --sidebar-accent-foreground: #3b2a1e;
  --ov-line: #b5462a2e; --ov-muted: #6a5444; --ov-dim: #7d6554;
  --ov-mode-conversation: #6b7445; --ov-mode-roleplay: #b5462a; --ov-mode-game: #9a6a14;
  --mari-mode-conversation: #6b7445; --mari-mode-roleplay: #b5462a; --mari-mode-game: #9a6a14;
  --mari-ctrlk-conversation: #6b7445; --mari-ctrlk-roleplay: #b5462a; --mari-ctrlk-game: #9a6a14;
  --mari-chrome-accent: #a63f24; --mari-chrome-muted: #6a5444;
  --mari-resource-accent: #a63f24;
  --mari-resource-characters: #b5462a; --mari-resource-personas: #8a5a2e; --mari-resource-lorebooks: #6b7445;
  --mari-resource-presets: #9a6a14; --mari-resource-connections: #5f6f6a; --mari-resource-agents: #8f3a1f;
  --mari-resource-settings: #6a5444; --mari-resource-backgrounds: #7a6a3a; --mari-resource-browser: #5f6f6a;
  --mari-lore-constant: #a63f24; --mari-lore-selective: #9a6a14; --mari-lore-normal: #6b7445;
  --mari-message-time: #7d6554;
  --mari-top-bar-plate: #fbf4e8d9; --mari-top-bar-plate-active: #f2dcc0;
  --mari-chat-header-bg: linear-gradient(#f6ecdcf2 60%, #f6ecdc00);
  --mari-game-combat: #a63f24; --mari-game-combat-text: #fffaf2;
  --mari-game-combat-bg: #a63f24; --mari-game-combat-bg-hover: #8f3a1f; --mari-game-combat-border: #6e2a14;
  --mari-home-pink: #b5462a; --mari-home-violet: #8a5a2e;
  --mari-home-widget-bg: #fbf4e8f2;
  --mari-home-widget-eyebrow-color: #a63f24;
  --mari-home-widget-title-color: #3b2a1e;
  --mari-home-widget-muted: #6a5444;
  --mari-home-wash: #f6ecdc8c;
  --mari-app-backdrop-layers:
     radial-gradient(ellipse 60% 70% at 52% 55%, #f6ecdc66 0%, #f6ecdc00 75%),
     url("theme:backdrop-day.webp") center / cover no-repeat;
  --mari-top-bar-bg: url("theme:topbar-band-day.webp") 0 100% / 1440px 100% repeat-x, #f6ecdc;
  --mari-page-veil: #f6ecdce0;
  --mari-chat-bg: #fbf4e8f2; --mari-chat-text: #3b2a1e; --mari-chat-border-color: #b5462a40;
  --mari-rp-bubble-bg: #fbf4e8;
  --mari-dialogue-color: #84361d;
  --mari-scrim: #3b2a1e59;
  --mari-stage-empty-bg: url("theme:backdrop-day.webp") center / cover;
  --mari-user-avatar-placeholder: linear-gradient(135deg, #d98a2b, #b5462a);
  --mari-art-saturation-1: 28%; --mari-art-lightness-1: 74%; --mari-art-saturation-2: 24%; --mari-art-lightness-2: 60%;
  --theo-panel: #fbf4e8f2;
  --theo-panel-solid: #fbf4e8;
  --theo-foot: url("theme:sidebar-foot.webp");
  --theo-band: url("theme:topbar-band-day.webp"); --theo-art: url("theme:backdrop-day.webp"); --theo-sheet-veil: #fbf4e8c7;
  --theo-char-avatar: url("theme:avatar-char.webp");
  --mari-user-avatar-image: url("theme:avatar-user.webp");
  --theo-rule: #b5462a59;
  --mari-message-actions: #7d6554; --mari-swipe-counter: #7d6554;
  --mari-focus-frame: url("theme:frame-focus.webp") 48 / 24px stretch;
}

/* ---------- NIGHT: lantern light on walnut ---------- */
:root[data-theme="dark"] {
  --background: #17120e; --foreground: #f3e6d0;
  --card: #241a13eb; --card-foreground: #f3e6d0;
  --popover: #241a13; --popover-foreground: #f3e6d0;
  --primary: #f0a848; --primary-foreground: #1c130b;
  --secondary: #2e2219; --secondary-foreground: #f3e6d0;
  --muted: #2b2018; --muted-foreground: #c9b49a;
  --accent: #3a2a1d; --accent-foreground: #ffdcae;
  --destructive: #e0644a; --destructive-foreground: #1c130b;
  --border: #f0a84830; --input: #f0a84845; --ring: #f0a848;
  --sidebar: #1c140fed; --sidebar-foreground: #f3e6d0; --sidebar-border: #f0a84826;
  --sidebar-accent: #2e2219; --sidebar-accent-foreground: #ffdcae;
  --ov-line: #f0a84826; --ov-muted: #c9b49a; --ov-dim: #a8927a;
  --ov-mode-conversation: #a3ad74; --ov-mode-roleplay: #e8774f; --ov-mode-game: #f0a848;
  --mari-mode-conversation: #a3ad74; --mari-mode-roleplay: #e8774f; --mari-mode-game: #f0a848;
  --mari-ctrlk-conversation: #a3ad74; --mari-ctrlk-roleplay: #e8774f; --mari-ctrlk-game: #f0a848;
  --mari-chrome-accent: #f0a848; --mari-chrome-muted: #c9b49a;
  --mari-resource-accent: #f0a848;
  --mari-resource-characters: #e8774f; --mari-resource-personas: #d9a066; --mari-resource-lorebooks: #a3ad74;
  --mari-resource-presets: #f0a848; --mari-resource-connections: #9fb3a8; --mari-resource-agents: #f08a5d;
  --mari-resource-settings: #c9b49a; --mari-resource-backgrounds: #cdb46a; --mari-resource-browser: #9fb3a8;
  --mari-lore-constant: #f08a5d; --mari-lore-selective: #f0a848; --mari-lore-normal: #a3ad74;
  --mari-message-time: #b09a80;
  --mari-top-bar-plate: #1c140fcc; --mari-top-bar-plate-active: #3a2a1d;
  --mari-chat-header-bg: linear-gradient(#17120ef2 60%, #17120e00);
  --mari-game-combat: #c4532f; --mari-game-combat-text: #fff3e0;
  --mari-game-combat-bg: #a8401f; --mari-game-combat-bg-hover: #c4532f; --mari-game-combat-border: #f0a84866;
  --mari-home-pink: #e8774f; --mari-home-violet: #d9a066;
  --mari-home-widget-bg: #241a13f0;
  --mari-home-widget-eyebrow-color: #f0a848;
  --mari-home-widget-title-color: #f8ecd8;
  --mari-home-widget-muted: #c9b49a;
  --mari-home-wash: #17120e8c;
  --mari-app-backdrop-layers:
     radial-gradient(ellipse 60% 70% at 52% 55%, #17120e40 0%, #17120e00 75%),
     url("theme:backdrop-night.webp") center / cover no-repeat;
  --mari-top-bar-bg: url("theme:topbar-band-night.webp") 0 100% / 1440px 100% repeat-x, #17120e;
  --mari-page-veil: #17120ee0;
  --mari-chat-bg: #241a13eb; --mari-chat-text: #eadcc4; --mari-chat-border-color: #f0a84838;
  --mari-rp-bubble-bg: #241a13;
  --mari-dialogue-color: #edb26a;
  --mari-scrim: #0a0705b3;
  --mari-stage-empty-bg: url("theme:backdrop-night.webp") center / cover;
  --mari-user-avatar-placeholder: linear-gradient(135deg, #f0a848, #c4532f);
  --mari-art-saturation-1: 22%; --mari-art-lightness-1: 30%; --mari-art-saturation-2: 18%; --mari-art-lightness-2: 18%;
  --theo-panel: #241a13f0;
  --theo-panel-solid: #241a13;
  --theo-frame: url("theme:frame-card-night.webp");
  --theo-shadow: 0 1px 2px #0006, 0 10px 28px #0000004d;
  --theo-foot: url("theme:sidebar-foot.webp");
  --theo-band: url("theme:topbar-band-night.webp"); --theo-art: url("theme:backdrop-night.webp"); --theo-sheet-veil: #1c140fb3;
  --theo-char-avatar: url("theme:avatar-char-night.webp");
  --mari-user-avatar-image: url("theme:avatar-user-night.webp");
  --theo-rule: #f0a8484d;
  --mari-message-actions: #b09a80; --mari-swipe-counter: #b09a80;
  --mari-focus-frame: url("theme:frame-focus-night.webp") 48 / 24px stretch;
}

/* Stock chat background steps aside so the path shows (a picked one stays). */
img[data-mari-part="backdrop"][data-default-background] { opacity: 0 !important; }

/* ---------- Sidebars: paper / walnut with a drift of leaves at the foot ---------- */
[data-component="ChatSidebar"], [data-component="RightPanelDesktop"] {
  background: var(--theo-foot) 100% calc(100% - 58px) / 230px auto no-repeat, var(--sidebar);
}
[data-chat-row][data-selected="true"] { box-shadow: inset 3px 0 0 var(--primary); }
:root[data-overhaul="mobile"] [data-component="ChatSidebar"] {
  background: var(--theo-foot) 100% calc(100% - 58px) / 200px auto no-repeat,
              var(--theo-band) 0 0 / 1440px 52px repeat-x,
              linear-gradient(var(--theo-sheet-veil), var(--theo-sheet-veil)),
              var(--theo-art) 30% 100% / cover no-repeat, var(--sidebar);
}

/* ---------- Signature frame: one inked double hairline + a maple leaf top-left ---------- */
[data-mari-part="home-widget"], .mari-rp-bubble, .mari-window, .mari-modal-panel, [data-component="GlobalOmnibar.Panel"],
[data-mari-part="message"][data-game-narration], [data-mari-part="message"][data-vn] {
  border: 16px solid transparent;
  border-image: var(--theo-frame) 48 / 24px stretch;
  background-clip: border-box !important;
  background-origin: border-box;
  border-radius: 12px;
  box-shadow: var(--theo-shadow);
}
[data-mari-part="home-widget"] { background: var(--mari-home-widget-bg); }
/* The card paints its own solid paper/walnut so the pinned name line (same colour) never shows as a band. */
.mari-rp-bubble { background: var(--theo-panel-solid) !important; }
[data-mari-part="message"][data-game-narration], [data-mari-part="message"][data-vn] { background-color: var(--theo-panel); }
/* One frame per card: the app's 1px chat outline would draw a second box inside the hairline. */
.mari-rp-bubble::before, .mari-rp-bubble::after { display: none !important; }

/* ---------- Roleplay: a calm reading column down the middle of the path ---------- */
/* (v1.5: the column, measure, line height and dialogue weight are tokens at the top.)
   Plain bold that isn't speech stays a touch lighter than stock bold. */
.mari-message-content strong:not([data-mari-part="dialogue"]) { font-weight: 600; }
.mari-message-content em { color: var(--muted-foreground); }
:root[data-theme="dark"] .mari-message-content em { color: #d8c6aa; }
.mari-message-content ol, .mari-message-content ul { padding-inline-start: 1.6em; margin-block: .25em; }
.mari-message-content li::marker { color: var(--primary); font-family: var(--mari-font-heading); font-weight: 600; }
/* Scene break (---): a small inked leaf between two hairlines. */
.mari-message-content hr {
  border: 0; height: 22px; margin: 6px 0;
  background:
    url("theme:cursor-leaf.png") center / 18px 18px no-repeat,
    linear-gradient(var(--theo-rule), var(--theo-rule)) left 22% center / calc(28% - 14px) 1px no-repeat,
    linear-gradient(var(--theo-rule), var(--theo-rule)) right 22% center / calc(28% - 14px) 1px no-repeat;
}
/* Cards dissolve before they reach the message box instead of poking out beneath it. */
.mari-messages-scroll:not([data-chat-mode="conversation"] *) {
  -webkit-mask-image: linear-gradient(#000 calc(100% - 96px), #0000 calc(100% - 20px));
  mask-image: linear-gradient(#000 calc(100% - 96px), #0000 calc(100% - 20px));
}

/* ---------- Messages ---------- */
[data-chat-mode="roleplay"] [data-mari-part="avatar"] > * { border-radius: 50%; box-shadow: 0 0 0 2px var(--theo-panel-solid), 0 0 0 3.5px var(--primary); }
[data-mari-part="message"] [data-mari-part="header"] { font-family: var(--mari-font-heading); letter-spacing: .01em; }
.mari-message-name { font-family: var(--mari-font-heading); font-size: 15px !important; letter-spacing: .01em; color: var(--foreground); }
/* Characters without a picture: an inked leaf medallion; you without one: a lantern. */
[data-mari-part="avatar-placeholder"][data-role="assistant"] { background: var(--theo-char-avatar) center / cover no-repeat !important; }
[data-mari-part="avatar-placeholder"][data-role="assistant"] > svg { display: none; }
/* Phones: the avatar column goes (--mari-phone-avatar); a thinner frame gives the text the room. */
@media (max-width: 600px) {
  .mari-rp-bubble { border-width: 12px; border-image-width: 18px; }
}

/* Conversation: one paper sheet down the middle instead of a stack of bars. */
[data-chat-mode="conversation"] .mari-messages-scroll {
  --theo-sheet: min(440px, 46%);
  background: linear-gradient(90deg, #0000 calc(50% - var(--theo-sheet) - 1px), var(--border) calc(50% - var(--theo-sheet) - 1px),
    var(--border) calc(50% - var(--theo-sheet)), var(--theo-panel) calc(50% - var(--theo-sheet)),
    var(--theo-panel) calc(50% + var(--theo-sheet)), var(--border) calc(50% + var(--theo-sheet)),
    var(--border) calc(50% + var(--theo-sheet) + 1px), #0000 calc(50% + var(--theo-sheet) + 1px));
}
/* The focus frame is for cards; a conversation line stays a line. */
[data-chat-mode="conversation"] [data-mari-part="message"][data-latest] { border-image: none !important; }
[data-chat-mode="conversation"] [data-mari-part="message"] { max-width: min(860px, 90%); margin-inline: auto; background: none; box-shadow: none; }
[data-composer="conversation"] .mari-chat-input-box { max-width: min(880px, 92%); margin-inline: auto; }

/* ---------- Composer & send ---------- */
[data-mari-part="composer"] .mari-chat-input-box { background: var(--theo-panel-solid); border-radius: 14px; box-shadow: var(--theo-shadow); }
.mari-chat-send-btn { background: radial-gradient(circle at 50% 35%, #f6c27a, #c4532f 78%) !important; color: #2a140a !important; border-radius: 999px; }

/* ---------- Pages, dialogs, Ctrl+K, toasts, menus ---------- */
[data-component="CenterContent"][data-center-page] h1, .mari-modal-panel h2 { font-family: var(--mari-font-heading); letter-spacing: .01em; }
[data-sonner-toast] {
  background: var(--theo-panel-solid) !important; color: var(--foreground) !important;
  border: 1px solid var(--border) !important; border-left: 3px solid var(--primary) !important;
  box-shadow: var(--theo-shadow) !important; border-radius: 10px !important;
}
[role="menu"], [role="listbox"] { box-shadow: var(--theo-shadow) !important; border-color: var(--border) !important; border-radius: 10px !important; }
/* Home link icons: warm them into the palette instead of stock purple/blue. */
[data-home-widget-id="learn"] :is(img,svg,picture), [data-home-widget-id="community"] :is(img,svg,picture) { filter: sepia(.85) saturate(1.25) hue-rotate(-12deg); }

/* No extra decorations in the message-extra slot (no HTML in this theme). */
[data-mari-part="message-extra"] { display: none; }
/* Story tag "spooky": the lantern night at any hour. */
:root[data-chat-tags~="spooky"] {
  --mari-app-backdrop-layers: linear-gradient(#ff6a0018, #2a0a0055), url("theme:backdrop-night.webp") center / cover no-repeat;
}

/* Cards without a picture: the leaf medallion on paper. */
:root[data-theme="light"] { --theo-card-paper: #efe2cc; }
:root[data-theme="dark"] { --theo-card-paper: #2e2219; }
:root { --mari-card-art-placeholder: var(--theo-char-avatar) center 42% / 58% auto no-repeat, var(--theo-card-paper); }
[data-mari-part="card-art"][data-placeholder] > svg { display: none; }

/* Auto-hiding top bar: leave room so a page title is never under the bar when it slides in (R5C5). */
:root[data-ov-topbar-autohide] [data-component="CenterContent"][data-center-page] { padding-top: calc(var(--mari-top-bar-height, 44px) - 6px); }
/* Phones: the long placeholder wraps in a narrow box. */
@media (max-width: 600px) { :root { --mari-composer-placeholder: "By lantern light…"; } }

/* High contrast: the leaves rest. */
:root[data-mari-contrast="more"] { --mari-ambient: none; }

/* Phones: the wide backdrop is cropped towards the tree (and its lantern at night) so the path
   still shows behind a narrow screen. */
@media (max-width: 600px) {
  :root[data-theme="light"] { --mari-app-backdrop-layers: linear-gradient(#f6ecdc59, #f6ecdc59), url("theme:backdrop-day.webp") 86% 0 / auto 100% no-repeat, #f6ecdc; }
  :root[data-theme="dark"] { --mari-app-backdrop-layers: linear-gradient(#17120e33, #17120e33), url("theme:backdrop-night.webp") 92% 0 / auto 100% no-repeat, #17120e; }
}

/* VN text box: the portrait is a round medallion like everywhere else, and smaller on phones so the
   paragraph keeps the width. */
[data-mari-part="message"][data-vn] > [data-mari-part="avatar"] { border-radius: 50%; border-color: transparent; box-shadow: 0 0 0 2px var(--theo-panel-solid), 0 0 0 3.5px var(--primary); }
@media (max-width: 600px) {
  [data-mari-part="message"][data-vn] > [data-mari-part="avatar"] { width: 44px !important; height: 44px !important; }
}
